<?php
namespace App\Http\Controllers; use App\Models\{Waste,WasteCategory}; use App\Http\Requests\{StoreWasteRequest,UpdateWasteRequest}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class WasteController extends Controller {public function index(Request $r){$wastes=Waste::with('category')->when($r->search,fn($q,$s)=>$q->where('name','like',"%$s%"))->when($r->category_id,fn($q,$id)=>$q->where('waste_category_id',$id))->orderBy($r->get('sort','name'),$r->get('dir','asc')==='desc'?'desc':'asc')->paginate(10)->withQueryString();$categories=WasteCategory::orderBy('name')->get();return view('wastes.index',compact('wastes','categories'));} public function create(){return view('wastes.form',['waste'=>new Waste,'categories'=>WasteCategory::orderBy('name')->get()]);} public function store(StoreWasteRequest $r){$d=$r->validated(); if($r->hasFile('image'))$d['image']=$r->file('image')->store('wastes','public');$d['is_active']=$r->boolean('is_active');Waste::create($d);return redirect()->route('wastes.index')->with('success','Jenis sampah berhasil ditambahkan.');} public function edit(Waste $waste){return view('wastes.form',['waste'=>$waste,'categories'=>WasteCategory::orderBy('name')->get()]);} public function update(UpdateWasteRequest $r,Waste $waste){$d=$r->validated();if($r->hasFile('image')){if($waste->image)Storage::disk('public')->delete($waste->image);$d['image']=$r->file('image')->store('wastes','public');}else unset($d['image']);$d['is_active']=$r->boolean('is_active');$waste->update($d);return redirect()->route('wastes.index')->with('success','Data sampah berhasil diubah.');} public function destroy(Waste $waste){$waste->delete();return back()->with('success','Data sampah dihapus (soft delete).');}}
